 $("start").addEventListener("click",()=>{if(game.command({type:game.state.phase==="won"?"continue":game.state.phase==="active"?"early":"wave"})){notice(game.state.phase==="ready"?"Endless continuation unlocked. Start the next wave.":"Wave "+game.state.wave+" begins."+(game.state.waveCalls.at(-1)?.early?" Early bonus +"+game.state.waveCalls.at(-1).bonus+" mana.":""));if(speed===0)setSpeed(1);selected=null;renderHud();}});
 $("upgrade").addEventListener("click",()=>{const t=game.state.towers[selected];if(!t)return;if(preview!=="upgrade"&&t.tier!==2){preview="upgrade";renderHud();return;}preview=null;if(t.tier===2){const pane=$("branchChoices");pane.replaceChildren();text($("branchTitle"),game.roster[t.kind].name+" · Choose specialization");for(const option of game.branchOptions(t)){const b=document.createElement("button"),name=document.createElement("strong"),desc=document.createElement("span"),ultimate=document.createElement("small"),price=document.createElement("em");b.type="button";b.dataset.branch=option.id;name.textContent=option.name;desc.textContent=option.description;ultimate.textContent="T4 · "+option.ultimate;price.textContent=game.upgradeCost(t).toLocaleString()+" mana";b.disabled=game.state.mana<game.upgradeCost(t);b.append(name,desc,ultimate,price);b.addEventListener("click",()=>{if(game.command({type:"upgrade",pad:selected,branch:option.id})){closeDialogs();notice(game.branchName(game.state.towers[selected])+" unlocked.");renderHud();}});pane.append(b);}showDialog("branchDialog");return;}if(game.command({type:"upgrade",pad:selected}))notice(game.branchName(t)+" upgraded.");renderHud();});
 $("sell").addEventListener("click",()=>{if(preview!=="sell"){preview="sell";renderHud();return;}preview=null;if(game.command({type:"sell",pad:selected})){rallying=false;selected=null;notice("Tower sold.");}renderHud();});
 $("rally").addEventListener("click",()=>{selectedCard=null;preview=null;rallying=!rallying;notice(rallying?"Tap a road location within this tower’s rally range.":"Rally selection cancelled.");renderHud();});
 function coords(e){const rect=canvas.getBoundingClientRect();return {x:(e.clientX-rect.left)*game.map.width/rect.width,y:(e.clientY-rect.top)*game.map.height/rect.height};}
 canvas.addEventListener("dragover",e=>e.preventDefault());
 canvas.addEventListener("drop",e=>{e.preventDefault();if(e.dataTransfer.types.includes("application/x-archamancy-card"))cast(Number(e.dataTransfer.getData("application/x-archamancy-card")),coords(e));});
 canvas.addEventListener("click",e=>{const {x,y}=coords(e);if(selectedCard!==null&&game.cards[game.state.hand[selectedCard]]?.target==="ground"){cast(selectedCard,{x,y});return;}if(moving){if(commanderAt(x,y)){cancelMove();return;}if(!onRoad(x,y)){cancelMove();if(selected!==null)selectPad(null);return;}moving=false;if(game.command({type:"commanderMove",x,y})){const q=game.pointAt(game.nearestPath(x,y));moveMark={x:q.x,y:q.y,at:performance.now()};movedOnce=true;sfx.play("click");$("notice").classList.remove("show");}else notice("Commander unavailable.");renderHud();return;}if(!rallying&&commanderAt(x,y)){selectCommander();return;}if(!rallying){if(selected!==null)selectPad(null);return;}if(game.command({type:"rally",pad:selected,x,y})){rallying=false;notice("Rally point moved.");}else notice("Choose a road position within the tower’s range.");renderHud();});
 function setSpeed(n){speed=n;accumulator=0;if(n)lastSpeed=n;const pb=document.querySelector("[data-speed='0']");if(pb){const want=n?"pause":"play";if(pb.dataset.icon!==want){pb.dataset.icon=want;pb.innerHTML=n?ICONS.pause:ICONS.play;pb.setAttribute("aria-label",n?"Pause":"Resume");}}for(const b of document.querySelectorAll("[data-speed]"))b.setAttribute("aria-pressed",String(Number(b.dataset.speed)===n));text($("speedCycle"),(n||lastSpeed)+"×");$("speedCycle").setAttribute("aria-pressed",String(n>1));}
 let lastSpeed=1;$("speedCycle").addEventListener("click",()=>setSpeed(speed===0?lastSpeed:speed>=3?1:speed+1));
 for(const b of document.querySelectorAll("[data-speed]"))b.addEventListener("click",()=>setSpeed(speed===0?lastSpeed:0));
 function restart(mode){clearRun();game=createEngine(1,mode);fx.reset();$("waveBanner").hidden=true;$("endScreen").hidden=true;seenWaves=0;if(mode!=="sandbox")game.command({type:"difficulty",level:profile.difficulty});applyDefaultCommander();selected=null;selectedCard=null;rallying=false;moving=false;schoolOpen=false;preview=null;heroKey="";lastEvent=-1;handKey="";contributionKey="";setSpeed(1);$("padSelect").value="";$("mode").value=mode;closeDialogs();notice("New "+mode+" run. Select a build pad.");renderHud();}
 $("restart").addEventListener("click",()=>restart(game.state.mode));
 $("newMode").addEventListener("click",()=>restart($("mode").value));
 function waveText(n){return game.waveSpec(n).map(x=>{const [k,c]=x.split(":"),d=game.types[k];return (d.boss&&k!=="titan"?"BOSS ":"")+d.name+" × "+c;}).join(" · ");}
 function traitText(n){const seen=new Set();return game.waveSpec(n).map(x=>x.split(":")[0]).filter(k=>game.types[k].trait&&!seen.has(k)&&seen.add(k)).map(k=>game.types[k].name+": "+game.types[k].trait).join(" ");}
 function ringLabel(b,icon,price,label){const k=icon+"|"+price;if(b.dataset.k!==k){b.dataset.k=k;const i=document.createElement("span"),c=document.createElement("span");i.className="ring-icon";i.textContent=icon;c.className="price";c.textContent=price;b.replaceChildren(i,c);}b.setAttribute("aria-label",label);b.title=label;}
 // Ring menu around the selected pad. Near the top or bottom edge the ring opens as an arc away from the edge.
 function placeRing(pad){const ring=$("ring"),rect=canvas.getBoundingClientRect(),unit=rect.height/game.map.height,rs=Math.max(38,Math.min(52,rect.width*.052)),reach=(rs*1.3+rs*.6)/unit;
  ring.style.left=pad.x/game.map.width*100+"%";ring.style.top=pad.y/game.map.height*100+"%";
  const py=rect.top+pad.y*unit,above=py-48,below=innerHeight-py-8,need=reach*unit,edge=above<need?"top":below<need?"bottom":"";ring.dataset.edge=edge;ring.dataset.info=!edge&&above<rs*1.95+64?"below":"";
  for(const group of ring.querySelectorAll(".ring-items")){const items=[...group.children].filter(b=>!b.hidden);const n=items.length;if(!n)continue;
   let angles;if(group.id==="towerActions"){angles=items.map(b=>b.id==="upgrade"?-90:b.id==="sell"?90:180);if(edge==="top")angles=angles.map(a=>a===-90?30:a===90?150:90);if(edge==="bottom")angles=angles.map(a=>a===-90?-90:a===90?-150:-30);}
   else if(!edge)angles=items.map((_,i)=>-90+i*360/n);else{const mid=edge==="top"?90:-90,span=n>3?150:130;angles=items.map((_,i)=>mid-span/2+(n===1?span/2:i*span/(n-1)));}
   items.forEach((b,i)=>{const a=angles[i]*Math.PI/180;b.style.setProperty("--cx",Math.cos(a).toFixed(3));b.style.setProperty("--cy",Math.sin(a).toFixed(3));});}
  const shift=Math.max(0,140-pad.x/game.map.width*rect.width)-Math.max(0,140-(game.map.width-pad.x)/game.map.width*rect.width);$("ringInfo").style.setProperty("--shift",shift+"px");}
 function renderHero(){const s=game.state,c=s.commander,key=c?c.id:"none";if(heroKey!==key+(cardArt.get(c?game.commanders[c.id].name:"")?"a":"")){heroKey=key+(cardArt.get(c?game.commanders[c.id].name:"")?"a":"");const face=$("heroFace");face.classList.remove("has-art");face.style.removeProperty("--art");face.textContent=c?"":"♛";if(c){if(!paintArt(face,game.commanders[c.id].name))face.textContent=game.commanders[c.id].name[0];$("commanderOpen").style.setProperty("--school",colors[game.commanders[c.id].color]);}else $("commanderOpen").style.removeProperty("--school");}
  const hp=c?(c.dead?0:c.hp/c.maxHp):0;$("heroHp").style.width=Math.round(hp*100)+"%";$("commanderOpen").classList.toggle("fallen",!!c&&c.dead);{const btn=$("commanderOpen"),down=!!c&&c.dead;if(down&&moving)moving=false;const left=down?Math.max(0,c.respawnAt-s.tick):0;btn.style.setProperty("--respawn",down?(1-left/game.commanderRespawn).toFixed(3):"0");const tm=$("heroTimer"),txt=down?String(Math.ceil(left/10)):"";if(tm.textContent!==txt)tm.textContent=txt;tm.hidden=!down;}$("commanderOpen").classList.toggle("selected",moving);$("commanderOpen").setAttribute("aria-label",c?game.commanders[c.id].name+(c.dead?", fallen, returns in "+Math.ceil(Math.max(0,c.respawnAt-s.tick)/10)+" seconds":", health "+c.hp+" of "+c.maxHp):"Choose a commander");}
